import json
from src.nodes.base import BaseNode
from src.runtime.layout import get_layout_review

class Hou_Mcp_Layout_Review(BaseNode):
    name = "hou_mcp_layout_review"

    def __init__(self):
        super().__init__()
        # [AUTO-GENERATED-PORTS-START]
        self.add_input("layout_plan_json",  "string", widget_type="text", default="{}")
        self.add_output("review_json",       "string")
        self.add_output("overall_score",     "float")
        self.add_output("grade",             "string")
        self.add_output("production_ready",  "bool")
        # [AUTO-GENERATED-PORTS-END]

    async def execute(self, inputs):
        raw = (inputs.get("layout_plan_json") or "").strip()

        try:
            plan = json.loads(raw) if raw else {}
        except Exception:
            self.log_error("layout_plan_json is not valid JSON.")
            return {"review_json": "{}", "overall_score": 0.0, "grade": "F", "production_ready": False, "exec_out": True}

        try:
            result = get_layout_review().review(plan)
            return {
                "review_json":     json.dumps(result.to_dict(), sort_keys=True, indent=2),
                "overall_score":   result.overall_score,
                "grade":           result.grade,
                "production_ready": result.production_ready,
                "exec_out": True,
            }
        except Exception as exc:
            self.log_error(f"Layout review failed: {exc}")
            return {"review_json": "{}", "overall_score": 0.0, "grade": "F", "production_ready": False, "exec_out": True}

def register_node():
    return Hou_Mcp_Layout_Review
